// Exercise multiple operator() overloads on a stateless hasher instance.
// Input object "hasher" is provided by the runtime and is non-null.

// 1) std::string overload: use bounded-size strings to control allocation.
std::string s1 = FUZZ_PARAM_STR();
if (s1.size() > 1024) { s1.resize(1024); }
size_t h1 = hasher->operator()(s1);
size_t h1b = hasher->operator()(s1);
// Determinism: hashing the same string twice should yield identical results.
FUZZ_ASSERT(h1 == h1b, "Deterministic hash for identical std::string input");

// 2) C-string overload (const T*&): provide a null-terminated string pointer reference.
// Use s1.c_str(), which is guaranteed to be null-terminated and readable.
const char *cptr = s1.c_str();
const char *&cptr_ref = cptr;  // bind lvalue reference to pointer as required by the API
size_t h2 = hasher->operator()(cptr_ref);
FUZZ_ASSERT(h2 == hasher->operator()(cptr_ref), "Deterministic hash for identical C-string input");

// 3) Raw bytes overload (const T* buf, size_t size): may pass null only when size==0.
std::string s2 = FUZZ_PARAM_STR();
if (s2.size() > 1024) { s2.resize(1024); }
bool use_null_buf = ((*FUZZ_PARAM(unsigned int)) % 4) == 0;  // occasionally test (nullptr, 0)
const char *raw = use_null_buf ? nullptr : s2.data();
size_t raw_sz = use_null_buf ? 0 : s2.size();
// Enforce API precondition: if size != 0 then buffer must be non-null.
if (raw_sz != 0 && raw == nullptr) { FUZZ_BAIL(); }
size_t h3 = hasher->operator()(raw, raw_sz);
FUZZ_ASSERT(h3 == hasher->operator()(raw, raw_sz), "Deterministic hash for identical raw buffer input");

// 4) std::thread::id overload: any valid id accepted; use the current thread id.
std::thread::id tid = std::this_thread::get_id();
( void )hasher->operator()(tid);

// 5) Literal array overload: call with a compile-time literal to hit this path.
( void )hasher->operator()("lit");

// 6) Integral overload: exercise both signed and unsigned integral types.
long long sval = *FUZZ_PARAM(long long);
( void )hasher->operator()(sval);
unsigned int uval = *FUZZ_PARAM(unsigned int);
( void )hasher->operator()(uval);

// 7) Non-char pointer overload: pass a non-char typed pointer; the pointee is not dereferenced.
int dummy = 0;
const int *ip = &dummy;  // T = int, which is not a character type
( void )hasher->operator()(ip);

// 8) std::shared_ptr overload: test both empty and non-empty shared_ptr.
bool make_empty_sp = ((*FUZZ_PARAM(unsigned int)) % 2) == 0;
std::shared_ptr<int> sp = make_empty_sp ? std::shared_ptr<int>() : std::make_shared<int>(*FUZZ_PARAM(int));
( void )hasher->operator()(sp);

// The hasher is stateless; return it to the pool as an output.

// Construct a stateless nebula::MurmurHash2 functor.
// This type is trivially default-constructible and user-managed.

nebula::MurmurHash2 *hasher = new (std::nothrow) nebula::MurmurHash2();
if (!hasher) { FUZZ_BAIL(); }

// Optional: mark as stateless; useful for downstream stubs if needed.
FUZZ_SET_ATTR_INT(hasher, "stateless", 1);

// Quick smoke test to ensure the instance is usable without violating API constraints.
// Use the raw-bytes overload with (nullptr, 0), which is explicitly allowed.
const char *null_buf = nullptr;
( void )hasher->operator()(null_buf, 0);

// Validation summary:
// - hasher is heap-allocated and non-null (checked), ownership returned via outputs.
// - No inputs consumed; object is ready for downstream operator() invocations.

